    static void pause(){try{Thread.sleep(600);}catch(InterruptedException e){Thread.currentThread().interrupt();}}
    List<AccessibilityNodeInfo> nodes(AccessibilityNodeInfo root){List<AccessibilityNodeInfo> n=new ArrayList<>();if(root==null)return n;n.add(root);for(int i=0;i<root.getChildCount();i++)n.addAll(nodes(root.getChild(i)));return n;}
