    boolean await(String s){for(int i=0;i<16;i++){if(has(s))return true;pause();}return false;}
    void click(String text){for(AccessibilityNodeInfo n:nodes())if(n.getText()!=null&&n.getText().toString().equals(text)){AccessibilityNodeInfo target=n;while(target!=null&&!target.isClickable())target=target.getParent();if(target!=null&&target.performAction(AccessibilityNodeInfo.ACTION_CLICK)){pause();return;}}throw new AssertionError("No clickable text: "+text);}
