    void widgetTop(){for(int i=0;i<40;i++){boolean moved=false;for(AccessibilityNodeInfo n:nodes())if("android.widget.ListView".contentEquals(n.getClassName())){moved=n.performAction(AccessibilityNodeInfo.ACTION_SCROLL_BACKWARD);break;}if(!moved)break;pause();}}
